"""Turn the checked-in test PEM files into one C header (`tls_peer_pki.h`), at build time.

    embed_pki.py OUT.h FILE.pem...

Each file becomes `static const char tls_peer_pem_<name>[]`, `<name>` being the file name without the
`.pem` suffix and with `.` replaced by `_`. Only the PEM blocks are embedded (the throwaway-key comment
line stays in the file). A file with anything but whole BEGIN/END blocks, an unknown label, or no block
at all fails the build, so the header is exactly the PEM test data and nothing else.
"""

import os
import re
import sys

BLOCK = re.compile(r"-----BEGIN ([A-Z ]+)-----\n(?:[A-Za-z0-9+/=]+\n)+-----END \1-----\n")
LABELS = ("CERTIFICATE", "PRIVATE KEY")
NAME = re.compile(r"[a-z0-9_]+(\.[a-z0-9_]+)*\.pem")


def pem_text(path):
    with open(path, "rb") as handle:
        text = handle.read().decode("ascii")
    lines = [line for line in text.splitlines(True) if not line.startswith("#")]
    body = "".join(lines)
    blocks = list(BLOCK.finditer(body))
    if not blocks or "".join(m.group() for m in blocks) != body:
        raise SystemExit("embed_pki: %s is not made of whole PEM blocks" % path)
    if any(m.group(1) not in LABELS for m in blocks):
        raise SystemExit("embed_pki: %s has an unexpected PEM label" % path)
    return body


def literal(text):
    return "\n".join('    "%s\\n"' % line for line in text.splitlines()) + ";"


def main(argv):
    if len(argv) < 2:
        raise SystemExit("usage: embed_pki.py OUT.h FILE.pem...")
    out, files = argv[0], sorted(argv[1:], key=os.path.basename)
    parts = ["/* generated by embed_pki.py from the checked-in PEM test data. Throwaway keys. */\n"
             "#ifndef TLS_PEER_PKI_H\n#define TLS_PEER_PKI_H\n"]
    for path in files:
        base = os.path.basename(path)
        if not NAME.fullmatch(base):
            raise SystemExit("embed_pki: unexpected file name %r" % base)
        ident = base[:-len(".pem")].replace(".", "_")
        parts.append("static const char tls_peer_pem_%s[] =\n%s\n" % (ident, literal(pem_text(path))))
    parts.append("#endif\n")
    with open(out, "w", encoding="ascii") as handle:
        handle.write("\n".join(parts))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
